\begin{Theorem}[\BookCite{67}]\label{thm:shifted-residual-collinearity}
{设 $W_1\subseteq W_2\subseteq\cdots\subseteq W_k$ 为 $\mathbb C^N$ 的子空间序列, 当 $i=1,2,\ldots,k$ 时满足 $\dim(W_i)=i$ 和 $W_i\cap\mathcal K_{i+1}(A,\bm b)^{\perp}=\{\bm0\}$. 设 $\bm x_i\in\mathcal K_i(A,\bm b)^{\perp}$ 为 $A\bm x=\bm b$ 的近似解, 由残差 $\bm r_i=\bm b-A\bm x_i=p_i(A)\bm b$ 的下列 Petrov--Galerkin 条件定义:}
\[\bm r_i\perp W_i\quad\text{for }i=1,2,\ldots,k,\]
{其中 $p_i(A)=\sum_{k=0}^i c_kA^i$. 类似地, 设 $\bm x_i^{\sigma}\in\mathcal K_i(A+\sigma I,\bm b)=\mathcal K_i(A,\bm b)$ 为 $(A+\sigma I)\bm x^{\sigma}=\bm b$ 的解的近似, 其残差 $\bm r^{\sigma}=\bm b-(A+\sigma I)\bm x_i^{\sigma}=p_i^{\sigma}(A+\sigma I)\bm b$ 同样满足}
\[\bm r_i^{\sigma}\perp W_i\quad\text{for }i=1,2,\ldots,k.\]
{则 $\bm r_i$ 与 $\bm r_i^{\sigma}$ 共线, 即存在 $\pi_i^{\sigma}\in\mathbb C$, 使得 $\bm r_i=\pi_i^{\sigma}\bm r_i^{\sigma}$.}
\end{Theorem}

\begin{Proof}
{设 $U_1,U_2$ 为 $\mathbb C^N$ 的子空间. 由标准线性代数可知, $(U_1\cap U_2)^{\perp}=U_1^{\perp}+U_2^{\perp}$. 由假设 $W_i\cap\mathcal K_{i+1}(A,\bm b)^{\perp}=\{\bm0\}$, 有}
\begin{equation}\label{eq:shifted-collinearity-complement-sum}(W_i\cap\mathcal K_{i+1}(A,\bm b)^{\perp})^{\perp}=\{\bm0\}^{\perp}\Leftrightarrow W_i^{\perp}+\mathcal K_{i+1}(A,\bm b)=\mathbb C^N.\end{equation}
{有 $\dim W_i^{\perp}=N-i$ 和 $\mathcal K_{i+1}(A,\bm b)=i+1$, 因而 $\dim W_i^{\perp}+\dim\mathcal K_{i+1}(A,\bm b)=N+1$. 另一方面, 由 \eqref{eq:shifted-collinearity-complement-sum}, 有 $\dim(W_i^{\perp}+\mathcal K_{i+1}(A,\bm b))=\dim\mathbb C^N=N$. 因此}
\[\dim(W_i^{\perp}\cap\mathcal K_{i+1}(A,\bm b))=1.\]
{由于 $\bm r_i,\bm r_i^{\sigma}\in\mathcal K_{i+1}(A,\bm b)\cap W_i^{\perp}$, 两个残差向量 $\bm r_i,\bm r_i^{\sigma}$ 位于同一个一维子空间中, 这意味着 $\bm r_i,\bm r_i^{\sigma}$ 共线.}\par\nopagebreak[4]\end{Proof}

{Theorem\ \ref{thm:shifted-residual-collinearity} 表明, 利用关系 $W_n=\mathcal K_n(A^{\mathrm H},\bm r_0^*)$, $A\bm x=\bm b$ 的 BiCG 残差向量 $\bm r_n$ 与 $(A+\sigma_k I)\bm x^{(k)}=\bm b$ 的 BiCG 残差向量 $\bm r_n^{(k)}$ 共线, 即}
\[\bm r_n=\pi_n^{(k)}\bm r_n^{(k)}.\]
{因此, 沿用 Section\ \ref{subsec:shifted-cg} 中移位 CG 方法的推导, 得到 Algorithm\ \ref{alg:shifted-bicg} 所列的移位 BiCG 方法算法. 类似地, Section\ \ref{subsec:bicr-method} 中的 BiCR 方法也被发展用于求解移位线性方程组, 在 \BookCite{85} 中称为移位 BiCR 方法.}

\begin{algorithm}[H]\caption{{移位 BiCG 方法}}\label{alg:shifted-bicg}\begin{algorithmic}[1]
\Statex\textbf{Input:} {选择种子系统 $s\in S=\{1,2,\ldots,m\}$ 并令 $\bm r_0^{(s)}=\bm b,\ \beta_{-1}^{(s)}=0$}
\Statex\textbf{Input:} $A$ {和} $\sigma_s$ {对于} $k=1,2,\ldots,m$
\Statex\textbf{Input:} $\bm x_0^{(k)}=\bm p_{-1}^{(k)}=\bm p_{-1}^{*(k)}=\bm0,\ \pi_0^{(s,k)}=\pi_{-1}^{(s,k)}=1$ {对于} $k=1,2,\ldots,m$
\Statex\textbf{Input:} {选择 $\bm r_0^*\in\mathbb C^N$, 例如 $\bm r_0^*=\bm r_0$}
\Statex\textbf{Output:} $\bm x_n^{(k)}$ {对于} $k=1,2,\ldots,m$
\For{$n=0,1,\ldots$, {直至收敛}}
\State $\bm p_n^{(s)}=\bm r_n^{(s)}+\beta_{n-1}^{(s)}\bm p_{n-1}^{(s)},\quad\bm p_n^{*(s)}=\bm r_n^{*(s)}+\bar\beta_{n-1}^{(s)}\bm p_{n-1}^{*(s)}$
\State $\alpha_n^{(s)}=\dfrac{(\bm r_n^{*(s)},\bm r_n^{(s)})}{(\bm p_n^{*(s)},A^{(s)}\bm p_n^{(s)})}$
\State $\bm x_{n+1}^{(s)}=\bm x_n^{(s)}+\alpha_n^{(s)}\bm p_n^{(s)}$
\State \{{移位系统开始}\}
\State {执行移位 CG 方法 (Algorithm\ \ref{alg:shifted-cg}) 的第 6--15 行.}
\State \{{移位系统结束}\}
\State $\bm r_{n+1}^{(s)}=\bm r_n^{(s)}-\alpha_n^{(s)}A^{(s)}\bm p_n^{(s)},\quad\bm r_{n+1}^{*(s)}=\bm r_n^{*(s)}-\bar\alpha_nA^{(s)\mathrm H}\bm p_n^{*(s)}$
\State $\beta_n^{(s)}=\dfrac{(\bm r_{n+1}^{*(s)},\bm r_{n+1}^{(s)})}{(\bm r_n^{*(s)},\bm r_n^{(s)})}$
\EndFor\end{algorithmic}\end{algorithm}

\[\begin{aligned}\bm p_n&:=Q_n(A)\bm p_n^{\mathrm{BiCG}}=\bm r_n+\beta_{n-1}(\bm p_{n-1}-\zeta_{n-1}A\bm p_{n-1})\\&=\bm r_n+\beta_{n-1}\left[\bm p_{n-1}+\frac{\zeta_{n-1}}{\alpha_{n-1}}(\bm t_{n-1}-\bm r_{n-1})\right],\\
\bm t_n&:=Q_n(A)\bm r_{n+1}^{\mathrm{BiCG}}=\bm r_n-\alpha_nA\bm p_n,\\
